local DrRayLibrary = loadstring(game:HttpGet("https://raw.githubusercontent.com/AZYsGithub/DrRay-UI-Library/main/DrRay.lua"))()
local window = DrRayLibrary:Load("Coolgod", "Default")

local tab = DrRayLibrary.newTab("AUTO FARM", "ImageIdHere")

tab.newButton("Auto Speed", "by Coolgod!", function()
   while task.wait() do
local args = {
	"PlayerStepAdd"
}
game:GetService("ReplicatedStorage"):WaitForChild("Packages"):WaitForChild("EventBus"):WaitForChild("RemoteEvent"):FireServer(unpack(args))
end
end)

tab.newButton("Auto Win", "by Coolgod!", function()
  while task.wait() do
game.Players.LocalPlayer.Character.HumanoidRootPart.CFrame = CFrame.new(-201.639999, 2247.98218, -34323.8242, 1, 0, 0, 0, 1, 0, 0, 0, 1)
end
end)

